14	Vocabulary Section	vocabulary		2	1.00	5
15	Listening Section	listening		3	1.00	5
16	Reading Section	reading	Grandmother fails test again. A sixty-eight-year-old grandmother from the South Korean city of Jeonju has just failed her written driving test for the 771st time. The woman's name, which was given only as Cha, first took the written part of the exam in April 2005. At the time, she thought it would help if she had a car for her job. In the beginning, Cha went to the licence office almost every day. Now, she no longer works but still goes to the office once a week. The office said she's spent more than £1,600 on exam fees. 'You have to get at least sixty points to pass the written part,' said Kim Rahn, who wrote about Cha in the Korea Times, an English-language daily newspaper. 'She usually gets under fifty.' Bloggers have already responded to the news about Mrs Cha's misfortunes with comments that range from sympathy to anger. One wrote, 'There's a time in every person's life when, if they fail something over 700 times, they should stop.' Other bloggers complained about a system that allows people to take a driving test so many times. One man commented: 'It's not a very good system if you can take the test as often as you want. I mean, she might be a danger to other people even if she passes the test after the 1,001st try.' Mrs Cha seems to be ignoring the bloggers. She said that she'd be back for another attempt. If she passes, then she can begin to prepare for the practical test.	4	1.00	5
17	Grammar Section	grammar		1	1.00	6
18	Vocabulary Section	vocabulary		2	1.00	6
19	Listening Section	listening		3	1.00	6
20	Reading Section	reading	These days, identity theft through the internet is a very real danger. While some people are cautious about the websites they use and the information they share, others are not. The criminals who target us know exactly what they are looking for. They also have a very clear idea of how they will use our information. The biggest problem is that we don't understand exactly what information they are trying to find. Perhaps if we did, we'd be more careful when using the internet. So, what can we do to keep our identity safe online? Well, the first piece of advice would be to install anti-virus software on the equipment you are using and to make sure it's kept up-to-date. Second, it's important to create new passwords for different websites. Never use the same one for two sites or purposes, especially the one which accesses your main email account. Remember also to only use secure online sites when you shop online and to use public wi-fi with extreme caution. People don't realise that when they're using this, it is incredibly easy for hackers to access their data. You should only use wi-fi hotspots for things you don't mind being public. So, the next time you're about to do some online banking or type in a password for a social networking site, stop and think. Ask yourself if you really want all the information you're about to share to go public.	4	1.00	6
21	Grammar Section	grammar		1	1.00	7
22	Vocabulary Section	vocabulary		2	1.00	7
23	Listening Section	listening		3	1.00	7
24	Reading Section	reading	Places that change lives. A: When Lucy Hopkins took a gap year before going to university, she could never have imagined how life-changing it would be. She decided to go travelling with a few friends. After hours of research on the internet, they finally bought round-the-world tickets and started their adventure in Australia. First stop: Ayers Rock and a five-day camping trip, exploring the gigantic sandstone monoliths of the area. But it wasn't the natural wonders that captured Lucy's imagination - it was the history of the Aboriginal people who had lived there long before European settlers arrived. She decided to stay on after her friends left. She wanted to find work at the resort so she could learn more about the Dreamtime, the myths and legends of these extraordinary people. Much to her parents' concern, she has given up her college place and will reapply next year for a course in anthropology. B: 'It's never too late to follow your dreams.' So said fifty-year-old yachtsman, Daniel Laws. He'd just returned from a six-month trip sailing around the Caribbean. When asked what had made him give up his job to take to the seas, he said that he'd fallen in love with the Indonesian island of Bali. From that moment on, he spent all his time either in or on the water and he promised himself that he would return when he had his own boat. C: Marek Lendl has always been passionate about history, particularly the history of his city, Prague. As a child, he was taken out every Sunday by his grandfather, who taught him about all the buildings, castles, churches and ruins. He is now a city guide, taking round groups of foreign tourists, and it is thanks to this passion that he met Emma, an English journalist who was on holiday in Prague.	4	1.00	7
